def Q(q,opts,pos):
    # opts: (correct, wrong1, wrong2, why_ok, why1, why2); pos 0..2 = position of correct
    c,w1,w2,ok,y1,y2=opts
    arr=[{'t':w1,'ok':False,'why':y1},{'t':w2,'ok':False,'why':y2}]
    arr.insert(pos,{'t':c,'ok':True,'why':ok})
    return {'q':q,'opts':arr}
